const d=StudyForge.data;const DAY=86400000;function score(q,answers,uncertain){const a=answers[q.id];return (uncertain[q.id]?100:0)+(a?.attempts||[]).filter(x=>x.correct===false||x.correct==null&&x.selected!==q.answer).length*10+(!a?1:0);}function nextDue(now,days){return now+days*DAY;}window.featureLogic={score,nextDue};let rows=[];
function element(tag,text){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;return el;}
function message(text){document.getElementById('message').textContent=text;}
function render(){const saved=StudyForge.state,reviews=saved.reviews||{},now=Date.now(),only=document.getElementById('due-only').checked;rows=(d.questions||[]).filter(q=>!only||!(reviews[q.id]?.due>now)).slice().sort((a,b)=>score(b,d.answers||{},d.uncertain||{})-score(a,d.answers||{},d.uncertain||{}));document.getElementById('queue-count').textContent=rows.length+'문제 · 저장한 복습일 '+Object.keys(reviews).length+'개';const box=document.getElementById('queue');box.replaceChildren();if(!rows.length)box.append(element('p',d.id?'지금 복습할 문제가 없어요.':'학습실을 만든 뒤 이 기능을 다시 열어 주세요.'));for(const q of rows){const item=element('article');item.append(element('small',q.topic+' · 우선점수 '+score(q,d.answers||{},d.uncertain||{})),element('strong',q.stem));const reveal=element('button','정답·해설 보기'),answer=element('p');answer.hidden=true;answer.textContent='정답 '+(q.answer+1)+'번: '+q.options[q.answer]+'\n'+q.explanation;reveal.addEventListener('click',()=>{answer.hidden=!answer.hidden;});item.append(reveal,answer);const date=element('small',reviews[q.id]?.due?'다음 복습: '+new Date(reviews[q.id].due).toLocaleDateString('ko-KR'):'복습일 미지정');item.append(date);const actions=element('div');actions.className='actions';for(const days of [1,3,7]){const button=element('button',days+'일 뒤 복습');button.addEventListener('click',async()=>{try{const value=StudyForge.state;value.reviews={...(value.reviews||{}),[q.id]:{due:nextDue(Date.now(),days),days}};await StudyForge.save(value);render();message(days+'일 뒤 복습으로 저장했어요.');}catch(e){message(e.message);}});actions.append(button);}item.append(actions);const note=element('textarea');note.setAttribute('aria-label','이 문제의 메모');note.value=saved.notes?.[q.id]||'';const save=element('button','메모 저장');save.addEventListener('click',async()=>{try{const value=StudyForge.state;value.notes={...(value.notes||{}),[q.id]:note.value};await StudyForge.save(value);message('메모를 저장했어요.');}catch(e){message(e.message);}});item.append(note,save);box.append(item);}}
document.getElementById('due-only').addEventListener('change',render);document.getElementById('practice').addEventListener('click',async()=>{try{await StudyForge.practice(rows.slice(0,200).map(q=>q.id));}catch(e){message(e.message);}});render();
